const ribbonFaq: Record<string, { question: string; answer: string }[]> = {
  wax: [
    { question: 'Do jakich etykiet nadaje się taśma woskowa?', answer: 'Taśma woskowa jest przeznaczona do druku na etykietach papierowych — powlekanych i niepowlekanych. Idealna do etykiet wysyłkowych, adresowych, magazynowych i logistycznych.' },
    { question: 'Jaka jest różnica między serią 2300 a 2100?', answer: 'Zebra 2100 ma formulację wzmocnioną żywicą — lepszą odporność na ścieranie i wyższą prędkość druku (355 vs 304 mm/s). Seria 2300 jest dostępna w formatach desktop i industrial, a 2100 tylko industrial.' },
    { question: 'Jak dobrać szerokość taśmy?', answer: 'Szerokość taśmy powinna być o 2–5 mm szersza niż etykieta. Chroni to głowicę drukującą przed bezpośrednim kontaktem z etykietą. Np. do etykiety 100 mm wybierz taśmę 102 lub 110 mm.' },
  ],
  'wax-resin': [
    { question: 'Kiedy wybrać taśmę woskowo-żywiczną zamiast woskowej?', answer: 'Wybierz woskowo-żywiczną, gdy etykiety są narażone na kontakt z rozpuszczalnikami, chemikaliami, wodą lub intensywne ścieranie. Taśma woskowa wystarcza do suchych warunków biurowych i magazynowych.' },
    { question: 'Czym różni się seria 3200 od 3400?', answer: 'Zebra 3400 oferuje lepszą jakość druku z rotowanymi kodami kreskowymi i większą trwałość. Jest dostępna tylko w formacie industrial (450 m). Seria 3200 jest dostępna też w wersji desktop (74 m) i jest bardziej uniwersalna.' },
    { question: 'Czy taśma 3200 ma certyfikat UL?', answer: 'Tak — seria 3200 posiada certyfikat UL, co potwierdza trwałość wydruku w testach ścierania i ekspozycji chemicznej. Jest wymagany np. dla etykiet GHS na pojemnikach chemicznych.' },
  ],
  resin: [
    { question: 'Do jakich etykiet nadaje się taśma żywiczna?', answer: 'Taśma żywiczna jest niezbędna do druku na etykietach syntetycznych — polipropylen (PP), polietylen (PE), poliester (PET). Zapewnia ekstremalną trwałość narażoną na chemikalia, temperaturę i ścieranie.' },
    { question: 'Czy taśma 5095 nadaje się do etykiet GHS?', answer: 'Tak — Zebra 5095 z certyfikatem UL/cUL jest standardem do druku etykiet GHS. W połączeniu z etykietami Z-Ultimate 2500T zapewnia zgodność z normami BS5609 dla oznaczeń chemicznych.' },
    { question: 'Jaka jest różnica między taśmą woskową, woskowo-żywiczną a żywiczną?', answer: 'Woskowa (WAX): ekonomiczna, do papieru, standardowe warunki. Woskowo-żywiczna (WAX/RESIN): do papieru powlekanego i syntetyków matowych, odporność na chemikalia. Żywiczna (RESIN): najtrwalsza, do syntetyków (PP/PE/PET), ekstremalna odporność.' },
  ],
}

