// Helper do pobrania produktu po slug
export function getProductBySlug(slug: string): Product | undefined {
  return products.find(p => p.slug === slug)
}

// Helper do filtrowania produktów
export function filterProducts(params: {
  categoryId?: string
  manufacturerId?: string
  tags?: ProductTag[]
  search?: string
  isNew?: boolean
  sortBy?: 'popularity' | 'price-asc' | 'price-desc' | 'newest'
}): Product[] {
  let filtered = [...products]

  if (params.categoryId) {
    filtered = filtered.filter(p => p.categoryId === params.categoryId)
  }

  if (params.manufacturerId) {
    filtered = filtered.filter(p => p.manufacturerId === params.manufacturerId)
  }

  if (params.tags && params.tags.length > 0) {
    filtered = filtered.filter(p =>
      params.tags!.some(tag => p.tags.includes(tag))
    )
  }

  if (params.search) {
    const searchLower = params.search.toLowerCase()
    filtered = filtered.filter(p =>
      p.name.toLowerCase().includes(searchLower) ||
      p.shortDescription.toLowerCase().includes(searchLower) ||
      p.description.toLowerCase().includes(searchLower)
    )
  }

  if (params.isNew) {
    filtered = filtered.filter(p => p.isNew)
  }

  // Sortowanie
  switch (params.sortBy) {
    case 'price-asc':
      filtered.sort((a, b) => (a.priceFrom || 0) - (b.priceFrom || 0))
      break
    case 'price-desc':
      filtered.sort((a, b) => (b.priceFrom || 0) - (a.priceFrom || 0))
      break
    case 'newest':
      filtered.sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime())
      break
    case 'popularity':
    default:
      filtered.sort((a, b) => (b.isBestseller ? 1 : 0) - (a.isBestseller ? 1 : 0))
  }

  return filtered
}

// Helper do pobrania bestsellerów
export function getBestsellers(limit: number = 6): Product[] {
  return products.filter(p => p.isBestseller).slice(0, limit)
}

// Helper do pobrania nowych produktów
export function getNewProducts(limit: number = 4): Product[] {
  return products.filter(p => p.isNew).slice(0, limit)
}

// Helper do pobrania kategorii po ID
export function getCategoryById(id: string): Category | undefined {
  return categories.find(c => c.id === id)
}

// Helper do pobrania producenta po ID
export function getManufacturerById(id: string): Manufacturer | undefined {
  return manufacturers.find(m => m.id === id)
}

// Helper do pobrania produktów po kategorii
export function getProductsByCategory(categoryId: string): Product[] {
  return products.filter(p => p.categoryId === categoryId)
}

// Helper do zliczenia produktów w kategorii
export function countProductsInCategory(categoryId: string): number {
  return products.filter(p => p.categoryId === categoryId).length
}

// Subcategory helpers
export function getSubcategoryBySlug(slug: string): Subcategory | undefined {
  return subcategories.find(s => s.slug === slug)
}

export function getSubcategoryById(id: string): Subcategory | undefined {
  return subcategories.find(s => s.id === id)
}

export function getProductsBySubcategory(subcategoryId: string): Product[] {
  const sub = getSubcategoryById(subcategoryId)
  if (!sub) return []
  return sub.productIds
    .map(id => products.find(p => p.id === id))
    .filter((p): p is Product => p !== undefined)
}

export function getSubcategoriesForCategory(categoryId: string): Subcategory[] {
  return subcategories.filter(s => s.parentCategoryId === categoryId && !s.parentSubcategoryId)
}

export function getChildSubcategories(parentSubcategoryId: string): Subcategory[] {
  return subcategories.filter(s => s.parentSubcategoryId === parentSubcategoryId)
}

export function getSubcategoriesForProduct(product: Product): Subcategory[] {
  if (!product.subcategoryIds) return []
  return product.subcategoryIds
    .map(id => getSubcategoryById(id))
    .filter((s): s is Subcategory => s !== undefined)
}

// Industry pages helper — pobiera produkty po tagu branżowym
export function getProductsByTag(tag: ProductTag): Product[] {
  return products.filter(p => p.tags.includes(tag))
}

// Pobiera produkty po wielu tagach (OR — dowolny z podanych)
export function getProductsByTags(tags: ProductTag[]): Product[] {
  return products.filter(p => tags.some(t => p.tags.includes(t)))
}

// Helper: typ nadrzędny taśmy (do breadcrumbów i hub pages)
export type RibbonParentType = 'wax' | 'wax-resin' | 'resin'

const ribbonParentTypeMap: Record<string, RibbonParentType> = {
  'tasmy-wax-2300': 'wax', 'tasmy-wax-2100': 'wax', 'tasmy-wax-1600': 'wax', 'tasmy-wax-5319': 'wax',
  'tasmy-wax-resin-3200': 'wax-resin', 'tasmy-wax-resin-3300': 'wax-resin', 'tasmy-wax-resin-3400': 'wax-resin', 'tasmy-wax-resin-5555': 'wax-resin',
  'tasmy-resin-4800': 'resin', 'tasmy-resin-5095': 'resin', 'tasmy-resin-5100': 'resin', 'tasmy-resin-chemresist': 'resin',
}

export function getRibbonParentType(subcategoryId: string): RibbonParentType | undefined {
  return ribbonParentTypeMap[subcategoryId]
}

// Helper: pobiera subcategorie ribbonów pogrupowane po typie
export function getRibbonModelSubcategories(): { wax: Subcategory[]; waxResin: Subcategory[]; resin: Subcategory[] } {
  const children = getChildSubcategories('tasmy-termotransferowe')
  return {
    wax: children.filter(s => ribbonParentTypeMap[s.id] === 'wax'),
    waxResin: children.filter(s => ribbonParentTypeMap[s.id] === 'wax-resin'),
    resin: children.filter(s => ribbonParentTypeMap[s.id] === 'resin'),
  }
}

